63	// Workspace per-tile byte sizes (all naturally 128-byte aligned)
64	template <int CHUNK, int D>
65	struct WorkspaceSizes {
66	    static_assert(CHUNK * D * 2 % 128 == 0);
67	    static_assert(D * 4 % 128 == 0);
68	    static_assert(CHUNK * CHUNK * 2 % 128 == 0);
69	
70	    static constexpr int kKDecayed  = CHUNK * D * 2;        // 4096
71	    static constexpr int kQDecayed  = CHUNK * D * 2;        // 4096
72	    static constexpr int kKRestored = CHUNK * D * 2;        // 4096
73	    static constexpr int kGTotal    = D * 4;                 // 512
74	    static constexpr int kINV       = CHUNK * CHUNK * 2;     // 512
75	    static constexpr int kMqk       = CHUNK * CHUNK * 2;     // 512
76	    static constexpr int64_t kPerTile = kKDecayed + kQDecayed + kKRestored + kGTotal + kINV + kMqk;
77	};
