167	template <class TensorA, class TensorB, class TensorC>
168	CUTLASS_DEVICE void mma_m16n16_bf16bf16fp32_1warp(
169	    TensorA const& A,
170	    TensorB const& B,
171	    TensorC& C,
172	    int mma_tid
173	) {
174	    auto mma = make_tiled_mma(
175	        SM80_16x8x16_F32BF16BF16F32_TN{},
176	        Layout<Shape<_1,_1>>{},
177	        Tile<_16,_16,_16>{}
178	    );
179	
180	    if (mma_tid >= int(size(mma))) return;
181	
182	    // Same accumulation chain as the fp16/bf16-store variants; only the
183	    // epilogue differs (raw fp32 accumulator stored elementwise).
184	    auto thr_mma = mma.get_slice(mma_tid);
185	    Tensor tCsC = thr_mma.partition_C(C);
186	    Tensor tCrC = thr_mma.make_fragment_C(tCsC);
187	    clear(tCrC);
188	
189	    cooperative_gemm(mma_tid, mma, A, B, tCrC, cute::identity{}, cute::identity{}, SM75_U32x4_LDSM_N{}, SM75_U32x4_LDSM_N{});
190	
191	    cute::copy(tCrC, tCsC);
192	}
