371	// ==================== FP32 <-> BF16 state conversion in SMEM ====================
372	// Both FP32 (K_SW32) and BF16 (K_INTER) layouts resolve to the same 8x8 atom
373	// structure with Swizzle<0,0,3>. Conversion operates per-atom:
374	//   - Each warp handles one 8x8 atom (64 elements)
375	//   - Each thread converts 2 elements
376	//   - Warp-level iteration over all atoms in the D x D state
377	
378	template <class FP32Layout, class BF16Layout, int D, int NumThreads>
379	__device__ void smem_cvt_fp32_to_bf16(
380	    float* __restrict__ fp32_smem,
381	    cutlass::bfloat16_t* __restrict__ bf16_smem,
382	    int tid
383	) {
384	    using BF16 = cutlass::bfloat16_t;
385	    constexpr int kBlock = 8;
386	    constexpr int kBlocksPerDim = D / kBlock;
387	    constexpr int kTotalBlocks = kBlocksPerDim * kBlocksPerDim;
388	    constexpr int kWarpSize = 32;
389	
390	    auto fp32_view = make_tensor(make_smem_ptr(fp32_smem), FP32Layout{});
391	    auto bf16_view = make_tensor(make_smem_ptr(bf16_smem), BF16Layout{});
392	
393	    int warp_id = tid / kWarpSize;
394	    int lane_id = tid % kWarpSize;
395	    int num_warps = NumThreads / kWarpSize;
396	
397	    for (int blk = warp_id; blk < kTotalBlocks; blk += num_warps) {
398	        int br = (blk / kBlocksPerDim) * kBlock;
399	        int bc = (blk % kBlocksPerDim) * kBlock;
400	        int e0 = lane_id * 2;
401	        int e1 = lane_id * 2 + 1;
402	        int r0 = br + e0 / kBlock, c0 = bc + e0 % kBlock;
403	        int r1 = br + e1 / kBlock, c1 = bc + e1 % kBlock;
404	        bf16_view(r0, c0) = BF16(fp32_view(r0, c0));
405	        bf16_view(r1, c1) = BF16(fp32_view(r1, c1));
406	    }
407	}
408	
409	template <class BF16Layout, class FP32Layout, int D, int NumThreads>
410	__device__ void smem_cvt_bf16_to_fp32(
411	    cutlass::bfloat16_t* __restrict__ bf16_smem,
412	    float* __restrict__ fp32_smem,
413	    int tid
414	) {
415	    constexpr int kBlock = 8;
416	    constexpr int kBlocksPerDim = D / kBlock;
417	    constexpr int kTotalBlocks = kBlocksPerDim * kBlocksPerDim;
418	    constexpr int kWarpSize = 32;
419	
420	    auto bf16_view = make_tensor(make_smem_ptr(bf16_smem), BF16Layout{});
421	    auto fp32_view = make_tensor(make_smem_ptr(fp32_smem), FP32Layout{});
422	
423	    int warp_id = tid / kWarpSize;
424	    int lane_id = tid % kWarpSize;
425	    int num_warps = NumThreads / kWarpSize;
426	
427	    for (int blk = warp_id; blk < kTotalBlocks; blk += num_warps) {
428	        int br = (blk / kBlocksPerDim) * kBlock;
429	        int bc = (blk % kBlocksPerDim) * kBlock;
430	        int e0 = lane_id * 2;
431	        int e1 = lane_id * 2 + 1;
432	        int r0 = br + e0 / kBlock, c0 = bc + e0 % kBlock;
433	        int r1 = br + e1 / kBlock, c1 = bc + e1 % kBlock;
434	        fp32_view(r0, c0) = bf16_to_f32(bf16_view(r0, c0));
435	        fp32_view(r1, c1) = bf16_to_f32(bf16_view(r1, c1));
436	    }
437	}
